 page=doc[pn-1];boxes=[pymupdf.Rect(t['bbox'])for t in c['tables']if t['page']==pn and t['columns']==3];words=[w for w in page.get_text('words')if not any(b.contains(pymupdf.Point((w[0]+w[2])/2,(w[1]+w[3])/2))for b in boxes)];native=clean(' '.join(w[4]for w in words));found=[i for i in r['items']if i['key']==f'fgb-native-outside-grid-p{pn}'];assert len(found)==1;(i,)=found;actual=clean(i['text']);results.append({'page':pn,'candidate_key':i['key'],'kind':i['kind'],'source_native_text':native,'candidate_text':actual,'same_collapsed_whitespace':native==actual,'only_pagination_marker':actual.isdigit()and actual==str(pn)})
